// ACP bridge: exposes one Agent Client Protocol agent (spawned, JSON-RPC over stdio) as a me plugin.
// The agent is initialized on start; methods map onto ACP's session lifecycle:
//   agent.info      -> the initialize result
//   session.new     -> session/new
//   session.prompt  -> session/prompt; each session/update is sent as op.update on streaming calls
//   session.cancel  -> session/cancel (cancelling a streaming session.prompt op does the same)
//
// Instance manifest example (plugins/acp-gjc/plugin.json, generated by renderManifest):
//   "run": { "command": ["bun", "../../bridges/acp/src/main.ts"] }
//   "permissions": ["shell"], "provides": { "methods": ["agent.info", "session.new", "session.prompt", "session.cancel"] }
// and in me.config.json / me.local.json:
//   "pluginConfig": { "acp-gjc": { "agent": { "command": "gjc", "args": ["--mode", "acp"] }, "cwd": "/abs/project" } }
import { isAbsolute } from "node:path";
import { definePlugin, RpcError } from "@me/sdk";
import { AgentConnection } from "./agent.ts";
import { toPromptBlocks, validateConfig } from "./config.ts";

let agent: AgentConnection | null = null;

function cwdParam(p: any): string | undefined {
  if (p?.cwd === undefined) return undefined;
  if (typeof p.cwd !== "string" || !isAbsolute(p.cwd)) throw new RpcError(-32602, "cwd must be an absolute path");
  return p.cwd;
}

const plugin = definePlugin({
  async onInit(info) {
    agent = new AgentConnection(validateConfig(info.config), `me:${info.pluginId}`);
    await agent.get();
  },
  async onShutdown() {
    await agent?.close();
  },
  methods: {
    "agent.info": () => agent!.info(),
    "session.new": (p: { cwd?: string }) => agent!.newSession(cwdParam(p)),
    "session.prompt": async (p: { sessionId?: string; prompt: unknown; cwd?: string }, ctx) => {
      let blocks;
      try {
        blocks = toPromptBlocks(p?.prompt);
      } catch (err) {
        throw new RpcError(-32602, (err as Error).message);
      }
      if (p.sessionId !== undefined && typeof p.sessionId !== "string") throw new RpcError(-32602, "sessionId must be a string");
      // Without a sessionId the turn runs in a fresh session; its id is in the result for follow-ups.
      const sessionId = p.sessionId ?? (await agent!.newSession(cwdParam(p))).sessionId;
      return agent!.prompt(sessionId, blocks, (u) => ctx.update(u), ctx.signal);
    },
    "session.cancel": async (p: { sessionId: string }) => {
      if (typeof p?.sessionId !== "string") throw new RpcError(-32602, "sessionId is required");
      await agent!.cancel(p.sessionId);
      return {};
    },
  },
});

await plugin.run();
